<?php $edit=!empty($job['id']);?><h1 class="h"><?=$edit?'Upravit zakázku':'Nová zakázka'?></h1><form class="form" method="post" action="<?=$edit?'/jobs/'.$job['id'].'/update':'/jobs/save'?>"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Zákazník</label><select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=((int)($job['customer_id']??0)==$c['id'])?'selected':''?>><?=\App\Core\View::e($c['company_name']?:trim(($c['first_name']??'').' '.($c['last_name']??'')))?></option><?php endforeach;?></select></div><div class="field"><label>Název</label><input name="name" value="<?=\App\Core\View::e($job['name']??'')?>" required></div><div class="field"><label>Popis</label><textarea name="description"><?=\App\Core\View::e($job['description']??'')?></textarea></div><div class="row"><input name="location" value="<?=\App\Core\View::e($job['location']??'')?>" placeholder="Místo"><input name="budget" type="number" step=".01" value="<?=\App\Core\View::e($job['budget']??0)?>" placeholder="Rozpočet"></div><div class="row"><input name="start_date" type="date" value="<?=\App\Core\View::e($job['start_date']??'')?>"><input name="end_date" type="date" value="<?=\App\Core\View::e($job['end_date']??'')?>"></div><div class="row"><select name="status"><option value="planned">Plánováno</option><option value="active" <?=($job['status']??'')==='active'?'selected':''?>>Probíhá</option><option value="done" <?=($job['status']??'')==='done'?'selected':''?>>Dokončeno</option><option value="cancelled" <?=($job['status']??'')==='cancelled'?'selected':''?>>Zrušeno</option></select><input name="notes" value="<?=\App\Core\View::e($job['notes']??'')?>" placeholder="Poznámky"></div><button class="btn primary">Uložit</button></form>